const input=$json;
const trigger=String(input.trigger_type ?? '');
const current=input.latest_contract ?? null;
const seen=new Set(Array.isArray(input.seen_provider_event_ids)?input.seen_provider_event_ids:[]);

if(input.human_lock){
  return {json:{status:'human_required',operations:[],blockers:['HUMAN_LOCK_ACTIVE']}};
}

if(trigger==='closing_ready'){
  if(current && ['preparing','sent','signed'].includes(current.status)){
    return {json:{
      status:'no_action',
      operations:[],
      contract_snapshot:current,
      blockers:[]
    }};
  }

  const nextVersion=Number(input.latest_contract_version ?? current?.contract_version ?? 0)+1;
  const key='contract:'+String(input.customer_event_id)+':v'+String(nextVersion);
  return {json:{
    status:'adapter_required',
    operations:[
      {
        action:'CREATE_CONTRACT_RECORD',
        idempotency_key:key,
        customer_event_id:input.customer_event_id,
        contract_version:nextVersion,
        provider:'autentique',
        status:'preparing',
        source_event_id:input.source_event_id ?? null
      },
      {
        action:'REQUEST_AUTENTIQUE_CREATE',
        idempotency_key:key,
        customer_event_id:input.customer_event_id,
        contract_version:nextVersion
      }
    ],
    blockers:['AUTENTIQUE_ADAPTER_NOT_CONNECTED']
  }};
}

if(trigger==='provider_webhook'){
  const providerEventId=input.provider_event_id ?? null;
  if(!providerEventId){
    return {json:{status:'dead_letter',operations:[{action:'DEAD_LETTER',error_class:'CONTRACT_PROVIDER_EVENT_ID_MISSING'}],blockers:['CONTRACT_PROVIDER_EVENT_ID_MISSING']}};
  }
  if(seen.has(providerEventId)){
    return {json:{status:'duplicate_noop',operations:[],blockers:[]}};
  }
  if(!current || !current.id){
    return {json:{status:'dead_letter',operations:[{action:'DEAD_LETTER',error_class:'CONTRACT_MAPPING_NOT_FOUND'}],blockers:['CONTRACT_MAPPING_NOT_FOUND']}};
  }

  const incoming=String(input.provider_status ?? '').toLowerCase();
  const rank={not_started:0,preparing:1,sent:2,signed:3};
  if(!['sent','signed','cancelled'].includes(incoming)){
    return {json:{status:'human_required',operations:[{action:'CREATE_HUMAN_TASK',reason_code:'CONTRACT_PROVIDER_STATUS_UNKNOWN'}],blockers:['CONTRACT_PROVIDER_STATUS_UNKNOWN']}};
  }

  if(incoming==='cancelled' && current.status==='signed'){
    return {json:{
      status:'human_required',
      operations:[
        {action:'ENABLE_HUMAN_LOCK',reason_code:'NON_STANDARD_POST_CONTRACT_CHANGE'},
        {action:'CREATE_HUMAN_TASK',reason_code:'NON_STANDARD_POST_CONTRACT_CHANGE'},
        {action:'RECORD_PROVIDER_EVENT',provider_event_id:providerEventId,ignored:false}
      ],
      blockers:['NON_STANDARD_POST_CONTRACT_CHANGE']
    }};
  }

  if(current.status==='signed' && incoming!=='signed'){
    return {json:{
      status:'stale_noop',
      operations:[{action:'RECORD_PROVIDER_EVENT',provider_event_id:providerEventId,ignored:true,reason_code:'SIGNED_CONTRACT_NO_REGRESSION'}],
      blockers:[]
    }};
  }

  if(incoming!=='cancelled' && rank[incoming] < (rank[current.status] ?? -1)){
    return {json:{
      status:'stale_noop',
      operations:[{action:'RECORD_PROVIDER_EVENT',provider_event_id:providerEventId,ignored:true,reason_code:'CONTRACT_STATUS_REGRESSION'}],
      blockers:[]
    }};
  }

  const operations=[
    {
      action:'UPDATE_CONTRACT_STATUS',
      contract_id:current.id,
      provider_event_id:providerEventId,
      from_status:current.status,
      to_status:incoming,
      source_event_id:input.source_event_id ?? null
    },
    {action:'RECORD_PROVIDER_EVENT',provider_event_id:providerEventId,ignored:false}
  ];
  if(incoming==='sent') operations.push({action:'EMIT_EVENT',event_type:'contract_sent',customer_event_id:input.customer_event_id});
  if(incoming==='signed') operations.push({action:'EMIT_EVENT',event_type:'contract_signed',customer_event_id:input.customer_event_id});

  return {json:{status:'planned',operations,blockers:[]}};
}

return {json:{status:'blocked',operations:[],blockers:['CONTRACT_TRIGGER_UNKNOWN']}};
